RouteModel::Node* closest_node = nullptr;
float min_distance = std::numeric_limits<float>::max();

// Iterate through all nodes in the graph
for (auto& node : graph.SNodes()) {
    // Check if the node is connected to any non-footway roads
    bool is_valid_node = false;
    if (graph.get_node_to_roadmap().find(node.index_) != graph.get_node_to_roadmap().end()) {
        for (const auto& road : graph.get_node_to_roadmap().at(node.index_)) {
            if (road->type != Model::Road::Type::Footway) {
                is_valid_node = true;
                break;
            }
        }
    }

    // Only consider nodes that are part of non-footway roads
    if (is_valid_node) {
        // Calculate distance from current node to target coordinates
        float current_distance = node.distance(RouteModel::Node(-1, nullptr, Model::Node{x, y, -1}));

        // Update closest node if current node is closer
        if (current_distance < min_distance) {
            min_distance = current_distance;
            closest_node = &node;
        }
    }
}

return closest_node;

